<label class="search-field"><x-icon name="search" size="18"/><input name="q" value="{{ request('q') }}" placeholder="Tìm nội dung truyền thông…" aria-label="Tìm kiếm"></label>
<select name="department_id" aria-label="Phòng ban"><option value="">Tất cả đơn vị</option>@foreach($departments as $department)<option value="{{ $department->id }}" @selected(request('department_id') == $department->id)>{{ $department->name }}</option>@endforeach</select>
<select name="status" aria-label="Trạng thái"><option value="">Tất cả trạng thái</option>@foreach($statuses as $status)<option value="{{ $status->value }}" @selected(request('status') === $status->value)>{{ $status->label() }}</option>@endforeach</select>
<select name="priority" aria-label="Ưu tiên"><option value="">Mức độ ưu tiên</option>@foreach(['low'=>'Thấp','normal'=>'Bình thường','high'=>'Cao','urgent'=>'Khẩn cấp'] as $value=>$label)<option value="{{ $value }}" @selected(request('priority') === $value)>{{ $label }}</option>@endforeach</select>
<details class="advanced-filters"><summary class="button secondary">Bộ lọc thêm</summary><div class="filter-popover"><label>Người phụ trách<select name="assignee_id"><option value="">Tất cả nhân sự</option>@foreach($assignees as $person)<option value="{{ $person->id }}" @selected(request('assignee_id') == $person->id)>{{ $person->name }}</option>@endforeach</select></label><label>Từ ngày đăng<input type="date" name="from" value="{{ request('from') }}"></label><label>Đến ngày đăng<input type="date" name="to" value="{{ request('to') }}"></label><label>Hạn xử lý<select name="deadline"><option value="">Tất cả</option><option value="soon" @selected(request('deadline')==='soon')>Sắp đến hạn (48 giờ)</option><option value="overdue" @selected(request('deadline')==='overdue')>Quá hạn</option></select></label></div></details>
<button class="button primary" type="submit">Lọc</button><a href="{{ url()->current() }}" class="reset-filter">Đặt lại</a>
